//! Std-only smoke runs of the diode libFuzzer targets (`fuzz/fuzz_targets/`
//! `diode_manifest`, `diode_import`, `diode_fec`): the same harness code
//! (`fuzz/harness/*.rs`, included by path) driven by the deterministic
//! mutator in `fuzz/harness/smoke.rs` over the committed seed corpora. See
//! `fuzz/README.md`. `ROBODR_FUZZ_ITERS` / `ROBODR_FUZZ_SECS` tune the runs.
//!
//! The seeds are real `Packer` output (findings, black-box bundles, with and
//! without Reed-Solomon parity), regenerated by `regenerate_seeds` (run with
//! `--ignored`). The seed tests below check they still take the success
//! path, so a format change cannot silently turn the corpus into garbage.

mod common;

#[path = "../../../fuzz/harness/diode_fec.rs"]
mod diode_fec;
#[path = "../../../fuzz/harness/diode_import.rs"]
mod diode_import;
#[path = "../../../fuzz/harness/diode_manifest.rs"]
mod diode_manifest;
#[path = "../../../fuzz/harness/smoke.rs"]
mod smoke;

use common::*;
use robodr_diode::manifest::{Manifest, MANIFEST_FILE, SIGNATURE_FILE};
use robodr_diode::{ImportConfig, Importer, PackConfig};

const DIR: &str = env!("CARGO_MANIFEST_DIR");

/// Every file of a packed batch directory, sorted by name.
fn batch_files(dir: &std::path::Path) -> Vec<(String, Vec<u8>)> {
    let mut v: Vec<(String, Vec<u8>)> = std::fs::read_dir(dir)
        .unwrap()
        .map(|e| {
            let e = e.unwrap();
            (
                e.file_name().to_string_lossy().into_owned(),
                std::fs::read(e.path()).unwrap(),
            )
        })
        .collect();
    v.sort();
    v
}

/// `(file name, diode_import input, manifest bytes)` of freshly packed
/// batches: findings only; findings + bundles with two parity files; and a
/// bundle-only batch whose signature the harness must re-create (flag 1).
fn packed_seeds() -> Vec<(&'static str, Vec<u8>, Vec<u8>)> {
    let mut out = Vec::new();
    let site = Site::new("fuzz-seeds");
    // 1. Findings only (seq 1), shipped signature.
    let b = site.packer().pack(&findings(3), &[], NOW).unwrap();
    let files = batch_files(&site.outbox.join(&b[0].name));
    let refs: Vec<(&str, &[u8])> = files
        .iter()
        .map(|(n, b)| (n.as_str(), b.as_slice()))
        .collect();
    let manifest = files
        .iter()
        .find(|(n, _)| n == MANIFEST_FILE)
        .unwrap()
        .1
        .clone();
    out.push((
        "seed-findings.bin",
        diode_import::join(0b010, &refs),
        manifest,
    ));

    // 2. Findings + bundles with parity (fresh unit state: a new site).
    let site2 = Site::new("fuzz-seeds-parity");
    let mut cfg = PackConfig::new(UNIT);
    cfg.parity_shards = 2;
    cfg.shard_size = 512;
    let b = site2
        .packer_cfg(cfg)
        .pack(&findings(2), &[bundle(2), bundle(1)], NOW)
        .unwrap();
    assert_eq!(b.len(), 1);
    let files = batch_files(&site2.outbox.join(&b[0].name));
    let refs: Vec<(&str, &[u8])> = files
        .iter()
        .map(|(n, b)| (n.as_str(), b.as_slice()))
        .collect();
    let manifest = files
        .iter()
        .find(|(n, _)| n == MANIFEST_FILE)
        .unwrap()
        .1
        .clone();
    out.push((
        "seed-parity.bin",
        diode_import::join(0b010, &refs),
        manifest,
    ));

    // 3. The same batch without its signature file, with one data file
    //    missing (rebuilt from parity), signed by the harness.
    let refs: Vec<(&str, &[u8])> = files
        .iter()
        .filter(|(n, _)| n != SIGNATURE_FILE && n != "bundle-0001.rbbx")
        .map(|(n, b)| (n.as_str(), b.as_slice()))
        .collect();
    let manifest2 = files
        .iter()
        .find(|(n, _)| n == MANIFEST_FILE)
        .unwrap()
        .1
        .clone();
    out.push((
        "seed-parity-repair.bin",
        diode_import::join(0b011, &refs),
        manifest2,
    ));
    out
}

#[test]
fn import_seeds_are_accepted() {
    for seed in smoke::corpus(DIR, "diode_import") {
        let (flags, files) = diode_import::split(&seed);
        let tmp = TempDir::new("fuzz-seed");
        let inbox = tmp.path().join("inbox");
        let dir = inbox.join("rdd_ugv-007_0000000000000001");
        std::fs::create_dir_all(&dir).unwrap();
        let mut has_sig = false;
        for (n, b) in &files {
            has_sig |= n == SIGNATURE_FILE;
            std::fs::write(dir.join(n), b).unwrap();
        }
        if flags & 1 != 0 {
            let m = &files.iter().find(|(n, _)| n == MANIFEST_FILE).unwrap().1;
            std::fs::write(dir.join(SIGNATURE_FILE), diode_import::signature_file(m)).unwrap();
            has_sig = true;
        }
        assert!(has_sig);
        let mut imp = Importer::open(ImportConfig::under(tmp.path()), keyring()).unwrap();
        let r = imp.run(diode_import::NOW).unwrap();
        assert_eq!(r.accepted.len(), 1, "{r:?}");
        // And through the harness itself.
        diode_import::run(&seed);
    }
    diode_import::cleanup();
}

#[test]
fn manifest_seeds_pass_check() {
    for seed in smoke::corpus(DIR, "diode_manifest") {
        let end = seed.iter().position(|&b| b == 0).unwrap_or(seed.len());
        let m: Manifest = serde_json::from_slice(&seed[..end]).unwrap();
        assert_eq!(m.check(), Ok(()));
        diode_manifest::run(&seed);
    }
}

#[test]
fn fec_seeds_run() {
    for seed in smoke::corpus(DIR, "diode_fec") {
        assert!(seed.len() > 11);
        diode_fec::run(&seed);
    }
}

#[test]
fn diode_manifest_smoke() {
    let seeds = smoke::corpus(DIR, "diode_manifest");
    smoke::run("diode_manifest", &seeds, 0xd10d_0001, &diode_manifest::run);
}

#[test]
fn diode_import_smoke() {
    let seeds = smoke::corpus(DIR, "diode_import");
    smoke::run("diode_import", &seeds, 0xd10d_0002, &diode_import::run);
    diode_import::cleanup();
}

#[test]
fn diode_fec_smoke() {
    let seeds = smoke::corpus(DIR, "diode_fec");
    smoke::run("diode_fec", &seeds, 0xd10d_0003, &diode_fec::run);
}

/// Regenerates the committed seed corpora. Run with
/// `cargo test -p robodr-diode --test fuzz_smoke -- --ignored regenerate_seeds`.
#[test]
#[ignore = "writes into fuzz/corpus; run manually to refresh seeds"]
fn regenerate_seeds() {
    let import_dir = smoke::corpus_dir(DIR, "diode_import");
    let manifest_dir = smoke::corpus_dir(DIR, "diode_manifest");
    let fec_dir = smoke::corpus_dir(DIR, "diode_fec");
    for d in [&import_dir, &manifest_dir, &fec_dir] {
        std::fs::create_dir_all(d).unwrap();
    }
    for (name, input, manifest) in packed_seeds() {
        std::fs::write(import_dir.join(name), &input).unwrap();
        let (_, files) = diode_import::split(&input);
        let mut m = manifest.clone();
        if let Some((_, sig)) = files.iter().find(|(n, _)| n == SIGNATURE_FILE) {
            m.push(0);
            m.extend_from_slice(sig);
        }
        std::fs::write(manifest_dir.join(name), &m).unwrap();
    }
    // FEC: k, m, len, mask[8], then data (+ length bytes).
    let mut a = vec![3, 1, 16, 0b101, 0, 0, 0, 0, 0, 0, 0];
    a.extend((0..80u8).map(|i| i.wrapping_mul(37)));
    std::fs::write(fec_dir.join("seed-k4-m2.bin"), &a).unwrap();
    let mut b = vec![30, 9, 64, 0xff, 0x0f, 0, 0x80, 0, 0, 0, 1];
    b.extend((0..3000u32).map(|i| (i * 7 + 1) as u8));
    std::fs::write(fec_dir.join("seed-k31-m10.bin"), &b).unwrap();
}
